import{_ as a,C as c,o as t,c as r,a6 as o,b as i,w as s,a as n,E as h,af as l}from"./chunks/framework.DIp0zHSV.js";const k=JSON.parse('{"title":"Chart Pipeline","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/charts.md","filePath":"architecture/charts.md","lastUpdated":1794278866000}'),p={name:"architecture/charts.md"};function u(m,e,g,f,y,b){const d=c("Mermaid");return t(),r("div",null,[e[1]||(e[1]=o('<h1 id="chart-pipeline" tabindex="-1">Chart Pipeline <a class="header-anchor" href="#chart-pipeline" aria-label="Permalink to &quot;Chart Pipeline&quot;">​</a></h1><blockquote><p>Internal architecture of <code>lcards-chart</code>: how <code>sources[]</code> become an ApexCharts chart that follows Home Assistant history live.</p></blockquote><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The chart card (<code>src/cards/lcards-chart.js</code>, <code>LCARdSChart extends LCARdSCard</code>, <code>CARD_TYPE = &#39;chart&#39;</code>) draws with <a href="https://apexcharts.com" target="_blank" rel="noreferrer">ApexCharts</a> 7 (<code>apexcharts</code> <code>^7.8.0</code> in <code>package.json</code>). Everything that is not the card element lives in <code>src/charts/</code>, as small modules that are mostly pure functions and are unit-tested in <code>tests/charts/</code>:</p><table tabindex="0"><thead><tr><th>Module</th><th>Role</th></tr></thead><tbody><tr><td><code>chart-config-migration.js</code></td><td><code>migrateChartConfig()</code>: rewrites legacy chart configs into the canonical <code>sources[]</code> form. Pure, idempotent, no imports</td></tr><tr><td><code>chart-sources.js</code></td><td><code>normalizeChartSources()</code>: migrates, then turns <code>sources[]</code> into series descriptors with a <code>kind</code> (<code>history</code>, <code>statistics</code>, <code>datasource</code>); <code>arrayChartProblem()</code> for range, box and candlestick types</td></tr><tr><td><code>chart-span.js</code></td><td><code>parseDuration()</code>, <code>computeSpan()</code>: the time window from <code>graph_span</code> and <code>span</code></td></tr><tr><td><code>chart-group-by.js</code></td><td><code>groupBy()</code>: buckets points (<code>avg</code>, <code>min</code>, <code>max</code>, <code>first</code>, <code>last</code>, <code>sum</code>, <code>median</code>, <code>delta</code>, <code>diff</code>, and the array functions <code>minmax</code>, <code>box</code>, <code>ohlc</code>)</td></tr><tr><td><code>chart-series-fetcher.js</code></td><td><code>ChartSeriesFetcher</code>: loads every series, keeps it live, trims it to the window, throttles delivery</td></tr><tr><td><code>chart-options-builder.js</code></td><td><code>buildChartOptions()</code>, <code>buildApexSeries()</code>, <code>windowAxis()</code>, <code>timeAxisData()</code>, <code>chartStyleDefaults()</code>: the complete ApexCharts options, shared by the card and the docs demos (<code>doc/.vitepress/theme/ChartDemo.vue</code>)</td></tr><tr><td><code>chart-time-labels.js</code></td><td><code>toWallClock()</code>, <code>pointsToWallClock()</code>, <code>chartTimeZone()</code>, <code>datetimeFormats()</code>, <code>tooltipTimeFormatter()</code>: time labels in Home Assistant&#39;s zone and clock</td></tr><tr><td><code>ApexChartsAdapter.js</code></td><td><code>ApexChartsAdapter.generateOptions()</code>: maps the card&#39;s <code>style</code> tree to ApexCharts options (per-type defaults, axes, legend, annotations, formatters, <code>chart_options</code> last)</td></tr></tbody></table><p>User-facing configuration: <a href="./../cards/chart/">Chart card</a> (series and time: <a href="./../cards/chart/series.html">Series and Time</a>; old configs: <a href="./../cards/chart/upgrading.html">Upgrading</a>).</p><hr><h2 id="flow" tabindex="-1">Flow <a class="header-anchor" href="#flow" aria-label="Permalink to &quot;Flow&quot;">​</a></h2>',9)),(t(),i(l,null,{default:s(()=>[h(d,{id:"mermaid-100",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20CFG%5B%22card%20config%3Cbr%2F%3E(setConfig%2C%20CoreConfigManager)%22%5D%20--%3E%20NORM%5B%22normalizeChartSources()%3Cbr%2F%3EmigrateChartConfig()%20in%20memory%22%5D%0A%20%20%20%20NORM%20--%3E%20SERIES%5B%22series%20descriptors%3Cbr%2F%3Ekind%3A%20history%20%2F%20statistics%20%2F%20datasource%22%5D%0A%20%20%20%20SERIES%20--%3E%20FETCH%5B%22ChartSeriesFetcher.start(series%2C%20%7B%20graph_span%2C%20span%20%7D)%22%5D%0A%20%20%20%20FETCH%20--%3E%20H%5B%22history%3A%20history%2Fstream%20subscription%3Cbr%2F%3E(hass.connection.subscribeMessage)%22%5D%0A%20%20%20%20FETCH%20--%3E%20S%5B%22statistics%3A%20recorder%2Fstatistics_during_period%3Cbr%2F%3E(sendMessagePromise%2C%20refetched%20on%20a%20timer)%22%5D%0A%20%20%20%20FETCH%20--%3E%20D%5B%22datasource%3A%20DataSource.subscribe()%3Cbr%2F%3Emain%20or%20processor%20buffer%22%5D%0A%20%20%20%20H%20--%3E%20FLUSH%5B%22_flush()%2C%20at%20most%20once%20per%20second%3Cbr%2F%3EwindowPoints()%3A%20trim%2C%20carry%2C%20group_by%22%5D%0A%20%20%20%20S%20--%3E%20FLUSH%0A%20%20%20%20D%20--%3E%20FLUSH%0A%20%20%20%20FLUSH%20--%3E%20UPD%5B%22card._onSeriesUpdate(index%2C%20points)%22%5D%0A%20%20%20%20UPD%20--%3E%7C%22first%20data%20in%20(all%20series%2C%20or%202.5%20s)%22%7C%20INIT%5B%22_initializeChart()%3Cbr%2F%3EloadApexCharts()%20lazy%20chunk%22%5D%0A%20%20%20%20INIT%20--%3E%20OPTS%5B%22buildChartOptions()%3Cbr%2F%3EchartStyleDefaults%20%2B%20style%20%2B%20rule%20patches%3Cbr%2F%3EApexChartsAdapter.generateOptions()%22%5D%0A%20%20%20%20OPTS%20--%3E%20APEX%5B%22new%20ApexCharts(container%2C%20options).render()%22%5D%0A%20%20%20%20UPD%20--%3E%7C%22chart%20ready%22%7C%20LIVE%5B%22chart.updateOptions(%7B%20xaxis%3A%20window%20%7D)%3Cbr%2F%3Echart.updateSeries(buildApexSeries())%22%5D%0A%20%20%20%20RULES%5B%22rule%20patch%20%2F%20alert%20mode%22%5D%20--%3E%20REOPT%5B%22_updateChartOptions()%3Cbr%2F%3Ecolours%2C%20stroke%2C%20fill%2C%20grid%2C%20legend%2C%20axes%2C%20...%22%5D%0A%20%20%20%20REOPT%20--%3E%20APEX%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<ol><li><strong>Config.</strong> <code>setConfig()</code> tears down any existing chart (<code>chart.destroy()</code>, generation counter bumped so a stale async init is dropped), calls <code>LCARdSCard.setConfig()</code> (CoreConfigManager merges <code>CHART_CARD_DEFAULTS</code>: <code>chart_type: line</code>, <code>height: 300</code>), and restarts loading once the card has had its first update.</li><li><strong>First update.</strong> <code>_handleFirstUpdate()</code> registers the card for rules (<code>_registerOverlayForRules(config.id || &#39;chart-&lt;guid&gt;&#39;, &#39;chart&#39;, tags)</code>) and calls <code>_startLoading()</code>.</li><li><strong>Loading.</strong> <code>_startLoading()</code> (<code>lcards-chart.js:233</code>) normalizes the sources, shows the static SVG preview instead when there are no series or the card is inside <code>hui-card-picker</code>, waits for config processing (card-local <code>data_sources</code> must exist before a datasource series attaches), and starts a <code>ChartSeriesFetcher</code>. A run counter makes sure only the latest call starts a fetcher.</li><li><strong>First draw.</strong> The chart is not created on the first series: drawing one series and adding the others as they arrive rescales the axis mid-animation. <code>_onSeriesUpdate()</code> waits until every series has delivered once, or <code>FIRST_DATA_WAIT_MS</code> (2500 ms) with whatever arrived, then sets <code>_dataArrived</code>; <code>updated()</code> calls <code>_initializeChart()</code> once <code>.chart-container</code> has a real size.</li><li><strong>Init.</strong> <code>_initializeChart()</code> builds the options, awaits <code>loadApexCharts()</code>, checks the card was not reconfigured or disconnected meanwhile, creates and renders the chart, and starts a <code>ResizeObserver</code> on the card container (100 ms debounce, 2 px hysteresis) that re-sends size, <code>plotOptions</code> and <code>grid</code>.</li><li><strong>Live.</strong> Later updates go straight to <code>chart.updateOptions({ xaxis: windowAxis() })</code> (the moving window) and <code>chart.updateSeries(buildApexSeries())</code>, with animations off for both calls.</li></ol><hr><h2 id="the-sources-model" tabindex="-1">The <code>sources[]</code> model <a class="header-anchor" href="#the-sources-model" aria-label="Permalink to &quot;The `sources[]` model&quot;">​</a></h2><p>Each <code>sources[]</code> item is one series. <code>normalizeChartSources()</code> (<code>src/charts/chart-sources.js:40</code>) drops items with neither <code>entity</code> nor <code>datasource</code> and gives the rest a <code>kind</code>:</p><table tabindex="0"><thead><tr><th>Item</th><th><code>kind</code></th><th>Data</th></tr></thead><tbody><tr><td><code>{ entity, attribute? }</code></td><td><code>history</code></td><td>Recorder state history for the window, then live changes</td></tr><tr><td><code>{ entity, statistics: { type, period } }</code></td><td><code>statistics</code></td><td>Long-term statistics (<code>type</code> default <code>mean</code>, <code>period</code> default <code>hour</code>). For <code>chart_type: rangeArea</code> without <code>group_by</code>, <code>fetchMinMax</code> fetches <code>min</code> and <code>max</code> per period instead</td></tr><tr><td><code>{ datasource, buffer? }</code></td><td><code>datasource</code></td><td>An LCARdS DataSource: its main buffer, or the processor buffer named by <code>buffer</code>. The source can be card-local (<code>data_sources</code>) or defined by another card</td></tr></tbody></table><p>Every kind also takes <code>group_by: { func, duration, fill }</code> and the display keys (<code>name</code>, <code>unit</code>, <code>float_precision</code>, <code>type</code>, <code>curve</code>, <code>stroke_width</code>, <code>stroke_dash</code>, <code>color</code>, <code>opacity</code>, <code>yaxis_id</code>). The <code>ChartSeries</code> typedef in <code>chart-sources.js</code> lists them.</p><p><strong>Array chart types.</strong> <code>rangeArea</code>, <code>rangeBar</code>, <code>boxPlot</code> and <code>candlestick</code> need array points (<code>ARRAY_CHART_TYPES</code>). <code>arrayChartProblem()</code> returns the message the card shows over the chart when a series cannot produce them: <code>rangeArea</code> needs <code>group_by.func: minmax</code> (or statistics, which fetch min/max), <code>boxPlot</code> needs <code>box</code>, <code>candlestick</code> needs <code>ohlc</code>, and <code>rangeBar</code> has no builder yet.</p><p><strong>Display.</strong> <code>_seriesDisplay()</code> names a series <code>name</code>, else the entity&#39;s <code>friendly_name</code>, else the entity id, else <code>&lt;datasource&gt; (&lt;buffer&gt;)</code>; the unit is <code>unit</code>, else the entity&#39;s <code>unit_of_measurement</code> (not for an attribute series).</p><hr><h2 id="series-fetcher-chartseriesfetcher" tabindex="-1">Series fetcher (<code>ChartSeriesFetcher</code>) <a class="header-anchor" href="#series-fetcher-chartseriesfetcher" aria-label="Permalink to &quot;Series fetcher (`ChartSeriesFetcher`)&quot;">​</a></h2><p><code>src/charts/chart-series-fetcher.js</code>. Constructed by the card with <code>getHass</code>, <code>getDataSourceManager</code>, <code>onUpdate(index, points)</code>, a log id, and the default <code>throttleMs</code> of 1000.</p><h3 id="entity-history-history-stream" tabindex="-1">Entity history: <code>history/stream</code> <a class="header-anchor" href="#entity-history-history-stream" aria-label="Permalink to &quot;Entity history: `history/stream`&quot;">​</a></h3><p><code>_startHistory()</code> (<code>:191</code>) subscribes with <code>hass.connection.subscribeMessage(callback, message, { resubscribe: false })</code>:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;history/stream&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  entity_ids</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [series.entity],</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  start_time</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">window</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;"> start,</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ISO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  end_time: &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">window</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;"> end,</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ISO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;,            // only when the window is not live</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  minimal_response: !needsAttributes,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  significant_changes_only: !needsAttributes,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  no_attributes: !needsAttributes</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>needsAttributes</code> (<code>historyNeedsAttributes()</code>, <code>src/core/data-sources/ha-history-utils.js:96</code>) is true for an <code>attribute</code> series. The first message replaces the series&#39; points (the history for the window); every later one appends the new states (re-sorting if one arrives out of order). <code>historyStatesToPoints()</code> converts states to numeric <code>{ t, v }</code> points through <code>toNumericValue()</code> (numbers parse, on/off style states become 1/0, anything else is dropped).</p><p>Reconnects: the subscription is made with <code>resubscribe: false</code>, and the fetcher listens for the connection&#39;s <code>ready</code> event itself, recomputes the window and subscribes again, so a reconnect never replays a stale start time (the same approach as Home Assistant&#39;s own history stream helper). The <code>ready</code> listener is removed in a microtask, because removing a listener while the connection dispatches <code>ready</code> skips the next listener (<a href="https://github.com/snootched/lcards/issues/381" target="_blank" rel="noreferrer">issue #381</a>).</p><h3 id="long-term-statistics-recorder-statistics-during-period" tabindex="-1">Long-term statistics: <code>recorder/statistics_during_period</code> <a class="header-anchor" href="#long-term-statistics-recorder-statistics-during-period" aria-label="Permalink to &quot;Long-term statistics: `recorder/statistics_during_period`&quot;">​</a></h3><p><code>_startStatistics()</code> (<code>:262</code>) sends <code>{ type: &#39;recorder/statistics_during_period&#39;, start_time, end_time (now at the latest), statistic_ids: [entity], period, types }</code> with <code>sendMessagePromise</code>, maps each row&#39;s <code>start</code> and the chosen type (or <code>[min, max]</code>) to points, and refetches on a timer: every 5 minutes for <code>5minute</code> and <code>hour</code>, every hour for <code>day</code>, <code>week</code> and <code>month</code> (<code>STATISTICS_REFRESH_MS</code>).</p><h3 id="datasource-series" tabindex="-1">DataSource series <a class="header-anchor" href="#datasource-series" aria-label="Permalink to &quot;DataSource series&quot;">​</a></h3><p><code>_startDataSource()</code> (<code>:309</code>) looks the source up in the shared <code>DataSourceManager</code>, subscribes, and on every emit reads the whole buffer again (<code>getProcessorBuffer(buffer)</code> or the main <code>buffer</code>, <code>getAll()</code>). A source that does not exist yet (another card defines it) is retried once after 2 s. See <a href="./subsystems/datasource-system.html">Data Source System</a> and <a href="./internals/datasource-buffers.html">Datasource Buffers</a>.</p><h3 id="window-and-delivery" tabindex="-1">Window and delivery <a class="header-anchor" href="#window-and-delivery" aria-label="Permalink to &quot;Window and delivery&quot;">​</a></h3><ul><li><strong>Window</strong> (<code>computeSpan(config, now, calendar)</code>, <code>src/charts/chart-span.js</code>): <code>graph_span</code> (default <code>24h</code>) ending now, or aligned with <code>span.start</code> / <code>span.end</code> to the current minute, hour, day, week, month or year, shifted by <code>span.offset</code>. <code>live</code> is true when the window contains now.</li><li><strong>Calendar</strong> (<code>localeCalendar(hass)</code>, <code>src/utils/ha-locale.js</code>): the fetcher&#39;s <code>_computeSpan()</code> reads hass on every call and passes <code>{ timeZone, weekStart }</code>, resolved as Home Assistant&#39;s frontend does (<code>resolve-time-zone.ts</code>, <code>first_weekday.ts</code>). <code>hass.locale.time_zone: server</code> gives <code>hass.config.time_zone</code>, <code>local</code> (or no hass, or an unknown zone) gives undefined, meaning the browser&#39;s zone. <code>hass.locale.first_weekday: language</code> derives the day from <code>hass.locale.language</code> (<code>Intl.Locale</code> week info, else a CLDR region table), <code>monday</code>..<code>sunday</code> are explicit, and anything else is Monday. With a zone, <code>startOfUnit()</code> / <code>endOfUnit()</code> read wall-clock fields with <code>Intl.DateTimeFormat</code> and convert midnights back with a two-pass offset lookup (correct across DST changes); hours and minutes are counted back from <code>now</code>, so half-hour zones and a repeated DST hour stay right. Without a zone they use local <code>Date</code> setters, as before. The docs <code>ChartDemo.vue</code> calls <code>computeSpan()</code> without a calendar (browser zone, Monday).</li><li><strong>Time labels</strong> (<code>src/charts/chart-time-labels.js</code>, applied by <code>timeAxisData()</code> in <code>chart-options-builder.js</code>): x-axis ticks and tooltip times are in the same zone as the window. ApexCharts 7 reads datetime values only in UTC or the browser&#39;s zone, and picks its own calendar ticks only while <code>xaxis.labels.formatter</code> is unset (its <code>Core.js</code> skips the <code>TimeScale</code> otherwise and falls back to evenly divided ticks from the window start), so a label formatter cannot do it. Instead, with hass and a datetime axis (not horizontal <code>bar</code> or <code>rangeBar</code>), every point and the window <code>min</code>/<code>max</code> move to the zone&#39;s wall clock written as UTC (<code>toWallClock()</code>: 22:30 in New York becomes 22:30Z; offsets cached per quarter hour) and the axis gets <code>datetimeUTC: true</code>, so ApexCharts places and names ticks as it would in that zone. <code>chartTimeZone(hass)</code> is the profile&#39;s zone (<code>resolveTimeZone()</code>), else the browser&#39;s. <code>xaxis.labels.datetimeFormatter</code> is ApexCharts&#39; own per-unit set, with <code>h:mm TT</code> times when <code>useAmPm(hass)</code> (<code>hass.locale.time_format</code>, as <code>use_am_pm.ts</code>); <code>tooltip.x.formatter</code> writes the date and time with <code>Intl.DateTimeFormat</code> in the user&#39;s language and clock (date only over 90 days, seconds under 10 minutes). In a DST fall-back the repeated hour would run backwards, so <code>pointsToWallClock()</code> keeps each series monotonic (that hour sits at the changeover instant). Date formats that see these values (<code>style.formatters.xaxis_label</code>, <code>{x|format}</code> in <code>style.formatters.tooltip</code>, horizontal bar time labels) go through <code>_formatDate(timestamp, format, hass, timeZone)</code>, which reads <code>context.timeZone</code>: <code>UTC</code> for wall-clock values, the zone itself for horizontal bars. User <code>chart_options</code> (such as <code>xaxis.labels.datetimeFormatter</code> or <code>tooltip.x</code>) still win. The card&#39;s live updates (<code>_windowAxis()</code>, <code>_buildApexSeries()</code>) call <code>timeAxisData()</code> too, so they match the full build. Without hass (<code>ChartDemo.vue</code>) nothing moves and ApexCharts keeps its defaults.</li><li><strong>Ticks</strong>: every 60 s (<code>WINDOW_TICK_MS</code>) the window is recomputed and every series re-delivered; an aligned window that rolled over (midnight for <code>span.start: day</code>) restarts every series.</li><li><strong>Throttle</strong>: points mark a series dirty; <code>_flush()</code> runs at most once per <code>throttleMs</code>. A rolling window is recomputed on every flush, so a point that just arrived is inside it.</li><li><strong>Points per series</strong> (<code>windowPoints()</code>): with <code>group_by</code>, <code>groupBy()</code> buckets from the window start to now; statistics are cut to the window; history and datasource series keep the last point before the window re-stamped at its start (<code>trimToWindow()</code>) and the last value carried to now (<code>carryToEnd()</code>), so lines reach both edges and an unchanged value still draws. History that scrolled out of a rolling window is dropped from memory on each flush.</li></ul><p><code>stop()</code> ends every subscription and timer. The card calls it from <code>_stopLoading()</code> (config change, disconnect).</p><hr><h2 id="options-and-the-apexcharts-adapter" tabindex="-1">Options and the ApexCharts adapter <a class="header-anchor" href="#options-and-the-apexcharts-adapter" aria-label="Permalink to &quot;Options and the ApexCharts adapter&quot;">​</a></h2><p><code>_buildChartOptions(width, height)</code> (<code>lcards-chart.js:519</code>):</p><ol><li><code>chartStyleDefaults(getToken)</code> reads the theme&#39;s <code>components.chart.*</code> tokens (<code>colors</code>, <code>gridColor</code>, <code>axisColor</code>, <code>strokeWidth</code>, <code>fontFamily</code>, <code>fontSize</code>) through <code>themeManager.getToken()</code>. The card records them as <code>built-in</code> provenance for every field the config does not set.</li><li>The card&#39;s <code>style</code>, with rule patches (<code>_getMergedStyleWithRules()</code>), is deep-merged over those defaults: user config always wins.</li><li><code>buildChartOptions()</code> (<code>chart-options-builder.js:121</code>) puts the x-axis type (<code>xaxis_type</code>, else <code>category</code> for horizontal <code>bar</code>, <code>datetime</code> for time charts) and the window <code>min</code>/<code>max</code> into <code>style.chart_options</code> (user <code>chart_options</code> still win), gives scatter series visible markers, resolves <code>theme:</code> tokens (<code>resolveThemeTokensRecursive</code>), and calls <code>ApexChartsAdapter.generateOptions(style, size, { hass, series, yaxis, span, timeZone })</code>. On a datetime axis with hass, the points, window and time label options are first moved to Home Assistant&#39;s wall clock (<code>timeAxisData()</code>, see <a href="#window-and-delivery">Window and delivery</a>).</li><li><code>generateOptions()</code> (<code>ApexChartsAdapter.js:84</code>) maps <code>style.*</code> (colours, stroke, fill, grid, axes, legend, markers, data labels, tooltip, theme, typography, animation presets) to ApexCharts options, applies per-type defaults (<code>_getChartTypeDefaults()</code>; radar and half gauges are fitted to the size), builds the zero line and threshold annotations, the locale (<code>_buildApexLocale(hass)</code>) and number formatting through <code>haFormatNumber()</code> (<a href="./internals/ha-entity-display.html">Home Assistant Entity Display</a>), deep-merges <code>style.chart_options</code> last, and resolves every remaining CSS variable to a concrete colour (<code>_resolveAllCssVariables()</code>): ApexCharts computes shades and gradients from colour strings in JavaScript, so <code>var()</code> cannot reach it.</li><li><code>buildApexSeries()</code> adds <code>series</code>: <code>{ name, data: [{ x: t, y: v }] }</code> per series for time charts (a series <code>type: column</code> becomes ApexCharts <code>bar</code>), the latest finite value per series for <code>pie</code>, <code>donut</code>, <code>radialBar</code> and <code>polarArea</code> (labelled with the series names), one entry per series for <code>treemap</code> and <code>radar</code>.</li></ol><h3 id="the-lazy-chunk-and-the-licence" tabindex="-1">The lazy chunk and the licence <a class="header-anchor" href="#the-lazy-chunk-and-the-licence" aria-label="Permalink to &quot;The lazy chunk and the licence&quot;">​</a></h3><p><code>loadApexCharts()</code> (<code>lcards-chart.js:63</code>) is a dynamic <code>import(&#39;apexcharts&#39;)</code> cached in a module-level promise (a failed load is not cached, so the next chart retries). Rollup puts ApexCharts in its own chunk under <code>custom_components/lcards/chunks/</code>, so a dashboard without a chart never downloads it. The editor&#39;s processor preview (<code>src/editor/components/datasources/lcards-processor-preview.js:289</code>) and the docs demos (<code>ChartDemo.vue</code>, <code>ProcessorLab.vue</code>) import it the same way.</p><p>ApexCharts is not MIT: it is dual-licensed, and LCARdS uses it under the free ApexCharts Community License (<code>scripts/data/third-party.json</code>; the licence text ships in <code>custom_components/lcards/THIRD_PARTY_NOTICES.txt</code>). See <a href="./../credits.html#bundled-libraries">About: Bundled Libraries</a>.</p><hr><h2 id="migration-and-upgrade-on-open" tabindex="-1">Migration and upgrade-on-open <a class="header-anchor" href="#migration-and-upgrade-on-open" aria-label="Permalink to &quot;Migration and upgrade-on-open&quot;">​</a></h2><p>Older chart configs used <code>source</code>, <code>data_source</code>, <code>series_names</code>, <code>history_hours</code>, <code>show_legend</code>, <code>max_points</code>, a root <code>attribute</code>, and <code>series_N</code> entries in <code>data_sources</code> generated by the old editor. <code>migrateChartConfig(config)</code> (<code>src/charts/chart-config-migration.js:96</code>) returns <code>{ config, changed, notes }</code>:</p><ul><li>A canonical config comes back unchanged (same object, <code>changed: false</code>), so the card&#39;s per-render call is cheap.</li><li>Series come from <code>source</code>, then <code>data_source</code>, then <code>sources</code> (the old precedence). A <code>series_N</code> data source used by one series and holding only <code>entity</code>, <code>attribute</code>, <code>history</code>, <code>name</code>, <code>type</code>, <code>yaxis</code> is inlined as <code>{ entity, attribute }</code>; other named sources become <code>{ datasource, buffer }</code> (old <code>buffer</code>/<code>key</code>/<code>buffer.key</code> selectors normalized, <code>main</code> meaning the main buffer); a bare entity id becomes <code>{ entity }</code>.</li><li>Unused <code>series_N</code> entries and old-editor placeholders are removed; <code>name</code>, <code>type</code> and <code>yaxis</code> are stripped from data sources; <code>history_hours</code> (or the largest inlined <code>history.hours</code>) becomes <code>graph_span</code>; <code>show_legend</code> becomes <code>style.legend.show</code>.</li><li><code>notes</code> lists every change in plain words (shown by the editor).</li></ul><p>Two places run it:</p><ul><li><strong>The card, in memory</strong> (<code>normalizeChartSources()</code> on every <code>_startLoading()</code>): legacy YAML keeps working and is never written back. The schema keeps the legacy keys, marked with <code>x-replacement</code> (<code>src/cards/schemas/chart-schema.js</code>), so they still validate.</li><li><strong>The editor, on open</strong> (<code>LCARdSChartEditor.setConfig()</code>, <code>src/editor/cards/lcards-chart-editor.js:53</code>): only the first <code>setConfig()</code> after the editor opens may upgrade. If it changed anything, the editor fires <code>config-changed</code> once after its first render, so Home Assistant&#39;s Save stores the upgrade and Cancel discards it. Later <code>setConfig()</code> calls (Home Assistant re-sends the config on every keystroke in its code editor) migrate for display only and never fire, so legacy YAML being typed is not rewritten. The Chart Studio dialog and the series list editor migrate their working copy the same way (<code>lcards-chart-studio-dialog.js:153</code>, <code>lcards-chart-series-list-editor.js:143</code>).</li></ul><p><code>tests/charts/chart-config-migration.test.js</code> covers the cases.</p><hr><h2 id="entity-access-the-documented-exception" tabindex="-1">Entity access: the documented exception <a class="header-anchor" href="#entity-access-the-documented-exception" aria-label="Permalink to &quot;Entity access: the documented exception&quot;">​</a></h2><p>Cards normally read entities through <code>subscribeToEntity()</code> (see <code>.github/instructions/cards.instructions.md</code>). That delivers current state only, and a chart needs history for a time window, so the chart is the one card that talks to the websocket directly: <code>ChartSeriesFetcher</code> subscribes to <code>history/stream</code> and calls <code>recorder/statistics_during_period</code> on <code>hass.connection</code>. It owns its cleanup (<code>stop()</code>, from <code>_onDisconnected()</code> through <code>_stopLoading()</code>) and its reconnect handling (the <code>ready</code> listener above). New cards that need history should reuse this fetcher rather than open their own raw subscriptions.</p><p>The card still uses the normal paths for everything else: <code>getEntityState()</code> for series names and units, the shared <code>DataSourceManager</code> for datasource series, and <code>LCARdSCard</code>&#39;s HASS handling for templates in <code>style</code> (<code>_processCustomTemplates()</code> pre-evaluates them for <code>_resolveTemplateValue()</code>).</p><hr><h2 id="rules-alert-mode-and-lifecycle" tabindex="-1">Rules, alert mode and lifecycle <a class="header-anchor" href="#rules-alert-mode-and-lifecycle" aria-label="Permalink to &quot;Rules, alert mode and lifecycle&quot;">​</a></h2><ul><li><strong>Rule patches</strong>: <code>_onRulePatchesChanged()</code> calls <code>_updateChartOptions()</code> when the chart is ready.</li><li><strong>Alert mode</strong>: <code>LCARdSCard</code> calls <code>_onAlertModeChanged()</code> as soon as the alert palette&#39;s CSS variables are written. Because the adapter resolved every colour to a concrete value, the chart cannot follow the variables by itself, so the card rebuilds the options and sends colours, stroke, fill, grid, legend, markers, data labels, tooltip and both axes to <code>chart.updateOptions()</code> (<code>_updateChartOptions()</code>, <code>lcards-chart.js:591</code>), without re-creating the chart.</li><li><strong>Disconnect</strong> (<code>_onDisconnected()</code>): stops the fetcher, disconnects the resize observer, destroys the chart, resets <code>_dataArrived</code>. <strong>Reconnect</strong> (<code>_onConnected()</code>): restarts loading if the card had its first update and has no fetcher.</li><li><strong>Sizing</strong>: <code>_getCardSize()</code> is <code>ceil(height / 50)</code> (default height 300); <code>getGridOptions()</code> defaults to 6 columns by 4 rows (minimum 4 by 2). Charts size to 100% of their container, so tests mount them with a definite height.</li><li><strong>Editor</strong>: <code>getConfigElement()</code> imports <code>lcards-chart-editor.js</code> on demand (a lazy chunk); visual editing is in the Chart Studio dialog (<code>src/editor/dialogs/lcards-chart-studio-dialog.js</code>).</li></ul><hr><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Covers</th></tr></thead><tbody><tr><td><code>tests/charts/chart-config-migration.test.js</code></td><td>Every legacy form, idempotence, notes</td></tr><tr><td><code>tests/charts/chart-series-fetcher.test.js</code></td><td><code>normalizeChartSources()</code>, <code>history/stream</code> messages and reconnect, statistics requests, datasource series, windowing</td></tr><tr><td><code>tests/charts/chart-span-groupby.test.js</code></td><td><code>computeSpan()</code>, <code>parseDuration()</code>, <code>groupBy()</code> functions and fills</td></tr><tr><td><code>tests/charts/chart-span-locale.test.js</code></td><td><code>ha-locale.js</code> time zone and first weekday; zoned day/week/month/year/hour windows (DST, UTC+5:30); the fetcher&#39;s window from hass. Fixed UTC instants, so it passes under any <code>TZ</code></td></tr><tr><td><code>tests/charts/chart-time-labels.test.js</code></td><td>Wall-clock values, <code>datetimeUTC</code>, 12/24 hour tick formats and tooltip times, <code>local</code> profile zone, no hass, user formats winning, DST fall-back, horizontal bars, the card&#39;s live path</td></tr><tr><td><code>tests/charts/chart-options-builder.test.js</code></td><td>Options and series per chart type, window axis</td></tr><tr><td><code>tests/charts/apex-adapter.test.js</code></td><td><code>ApexChartsAdapter</code> mapping</td></tr><tr><td><code>tests/charts/chart-style-precedence.test.js</code></td><td>Theme defaults &lt; style &lt; rule patches</td></tr></tbody></table><p>Rendering is checked in the browser layer (<code>tests/browser/</code>, fixtures under <code>tests/browser/fixtures/</code>) and the docs demos.</p><hr><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./../cards/chart/">Chart card</a> (user docs)</li><li><a href="./cards/lcards-card-foundation.html">Card Foundation</a></li><li><a href="./subsystems/datasource-system.html">Data Source System</a></li><li><a href="./subsystems/theme-system.html">Theme System</a></li><li><a href="./subsystems/rules-engine.html">Rules Engine</a></li></ul>',51))])}const C=a(p,[["render",u]]);export{k as __pageData,C as default};
